static void idle(ux::Shell& s,Canvas& c){until([&]{s.tick();c.changes();CHECK(!s.failed());return s.writable()&&s.styledInk()&&!s.styledInk()->status().busy&&!s.unsaved();});}
static bool attempted(const Path& app){return std::filesystem::exists(app/"network-attempt");}
static input_event ev(unsigned short type,unsigned short code,int value){input_event e{};e.type=type;e.code=code;e.value=value;return e;}
